    ("Alexei von Jawlensky: Abstract Head: Sunrise", "Alexei von Jawlensky", 1926, "Oil on board", "Expressionism / Abstract", ["abstract","spiritual","simplified head","color","meditative"], ["simplified face","color","meditation","spiritual","abstract"], ["orange","cream","dark outlines","glowing"], "Various collections", "A simplified face — two lines for nose and brow, oval for eyes — glows in orange and gold against a dark ground.", "Jawlensky's late 'Meditation' series reduced the face to pure spiritual essence — a mandala of simplified human presence.", "male", "Russian"),

    # ── ADDITIONAL SURREALISM ─────────────────────────────────────────────
    ("Paul Delvaux: Sleeping Venus", "Paul Delvaux", 1944, "Oil on canvas", "Surrealism / Belgian", ["surrealist","dreamlike","nocturnal","nude","train station"], ["Venus sleeping","train station","classical figures","night","Belgian"], ["blue night","pale skin","classical architecture","gas lights"], "Tate Modern, London", "A nude Venus sleeps in a train station at night while ghosts of classical figures wander and a skeleton gestures.", "Delvaux's dreamscapes combine the erotic, the nocturnal, and the uncanny in a Belgian art nouveau space. Magritte called him the most surrealist Belgian artist.", "male", "Belgian"),
    ("Kay Sage: Tomorrow Is Never", "Kay Sage", 1955, "Oil on canvas", "Surrealism / American", ["surrealist","architectural","desolate","geometric","metaphysical"], ["draped forms","architectural spaces","mysterious","absence"], ["grey","cream draped","shadow blue","desolate"], "Metropolitan Museum of Art, New York", "Draped geometric forms rise in a desolate architectural space — the drapes suggest both covered furniture and shrouded figures.", "Sage was one of the few American-born Surrealists. Her geometric architectural Surrealism has a uniquely desolate quality unlike any European counterpart.", "female", "American"),
    ("Meret Oppenheim: Object (Luncheon in Fur)", "Meret Oppenheim", 1936, "Cup, saucer and spoon covered in fur", "Surrealism / Swiss", ["object","fur","uncanny","teacup","surrealist sculpture"], ["teacup","saucer","spoon","fur","uncanny"], ["brown fur","domestic white beneath"], "Museum of Modern Art, MoMA", "A teacup, saucer, and spoon lined with the fur of a Chinese gazelle.", "The most concise Surrealist object ever made. The fur's tactile implications in relation to drinking transform a domestic object into something disturbing.", "female", "Swiss"),
    ("Dorothea Tanning: Birthday", "Dorothea Tanning", 1942, "Oil on canvas", "Surrealism / American", ["surrealist","female","fantasy","doorways","creature"], ["woman","open doorways","strange creature","fantasy","halls"], ["dark red","cream","strange creature colors"], "Philadelphia Museum of Art", "Tanning in a fantastical jacket stands before infinite doorways opening on each other, a strange winged creature at her feet.", "The painting that made Tanning famous after Max Ernst saw it on his studio visit. The infinite doorways suggest the Surrealist unconscious.", "female", "American"),
    ("Roberto Matta: The Earth Is a Man", "Roberto Matta", 1942, "Oil on canvas", "Surrealism / Chilean", ["surrealist","cosmic","energetic","geological","large scale"], ["geological forms","energy fields","cosmic","landscape"], ["deep space","orange","blue","explosive"], "Art Institute of Chicago", "Vast geological and cosmic forces erupt in a field of pure energy — the Earth as sentient organism.", "Matta introduced a cosmic geological surrealism to New York that influenced the Abstract Expressionists directly. Pollock acknowledged his influence.", "male", "Chilean"),

    # ── ADDITIONAL ABSTRACT EXPRESSIONISM ────────────────────────────────
    ("Bradley Walker Tomlin: Number 20", "Bradley Walker Tomlin", 1949, "Oil on canvas", "Abstract Expressionism / American", ["abstract","calligraphic","white","gestural","sign-like"], ["white calligraphy","dark ground","marks","signs","abstract"], ["white","dark brown","calligraphic marks"], "Museum of Modern Art, MoMA", "White calligraphic marks float on a dark ground — somewhere between writing and pure gestural mark-making.", "Tomlin's synthesis of Cubist structure and gestural expression created some of the most elegant Abstract Expressionist works.", "male", "American"),
    ("James Brooks: Prana", "James Brooks", 1956, "Oil on canvas", "Abstract Expressionism / American", ["abstract","stained","organic","lyrical","earthy"], ["poured paint","organic form","color field","earthy","lyrical"], ["ochre","grey blue","cream","organic shapes"], "Various collections", "Poured and stained organic forms in earthy ochre and grey suggest landscape and organic life.", "Brooks was among the first to pour and stain paint before Frankenthaler, creating organic abstract fields between Pollock and Color Field.", "male", "American"),
    ("Conrad Marca-Relli: Seated Figure", "Conrad Marca-Relli", 1953, "Canvas collage on canvas", "Abstract Expressionism / American", ["collage","figurative abstraction","canvas on canvas","powerful","monochromatic"], ["figure","torn canvas","monochromatic","gestural","collage"], ["cream","dark grey","torn canvas textures"], "Various collections", "A seated figure assembled from torn pieces of canvas collaged onto canvas — figure and abstraction in one.", "Marca-Relli's torn-canvas collages occupy a unique position between Abstract Expressionism and Cubism.", "male", "American"),

    # ── POP ART INTERNATIONAL ─────────────────────────────────────────────
    ("Richard Hamilton: Just What Is It That Makes Today's Homes So Different, So Appealing?", "Richard Hamilton", 1956, "Collage", "Pop Art / British", ["pop art","collage","consumer culture","irony","first pop"], ["bodybuilder","female","television","consumer goods","modern home"], ["vivid consumer color","collage fragments","flat"], "Kunsthalle Tübingen", "A bodybuilder and a model in a living room crammed with consumer goods — the founding work of British Pop Art.", "The first 'Pop Art' image — the term was coined about this work. Hamilton defined Pop's subject matter: consumer goods as the new gods.", "male", "British"),
    ("Roy Lichtenstein: Whaam!", "Roy Lichtenstein", 1963, "Acrylic on canvas (two panels)", "Pop Art / American", ["pop art","comic book","war","onomatopoeia","bold"], ["fighter jet","missile","explosion","comic book","WHAAM!"], ["red","yellow","blue","Ben-Day dots","black outline"], "Tate Modern, London", "A fighter jet fires a missile; in the right panel the target explodes with the word 'WHAAM!'. Taken directly from a comic book.", "Lichtenstein's two-panel war comic is Pop Art's most spectacular painting. The Ben-Day dot technique transforms commercial illustration into monumental painting.", "male", "American"),
    ("Roy Lichtenstein: Drowning Girl", "Roy Lichtenstein", 1963, "Oil and acrylic on canvas", "Pop Art / American", ["pop art","comic book","female distress","ironic","bold"], ["drowning woman","waves","thought bubble","Brad","distress"], ["blue water","pink face","thought bubble text","Ben-Day"], "Museum of Modern Art, MoMA", "A woman drowns with a thought bubble reading 'I don't care! I'd rather sink than call Brad for help!'", "Lichtenstein transforms the melodrama of romance comics into monumental painting. The ironic emotional overstatement is entirely deadpan.", "male", "American"),
    ("James Rosenquist: F-111", "James Rosenquist", 1965, "Oil on canvas (86-panel)", "Pop Art / American", ["pop art","panoramic","war","consumer culture","large scale"], ["F-111 jet","spaghetti","girl under hair dryer","atomic cloud","consumer goods"], ["vivid consumer colors","orange","blue","white"], "Museum of Modern Art, MoMA", "The F-111 fighter-bomber runs the entire length of a 26-meter canvas, overlaid with consumer images — spaghetti, a girl under a dryer, an atomic blast.", "The longest Pop Art painting. A critique of the military-industrial complex wrapped in consumer imagery. Intended to wallpaper a room.", "male", "American"),
    ("Tom Wesselmann: Great American Nude #57", "Tom Wesselmann", 1964, "Assemblage and oil on canvas", "Pop Art / American", ["pop art","assemblage","nude","consumer","american"], ["nude figure","flat","american flag","consumer goods","assemblage"], ["red white blue","flat flesh","stars and stripes"], "Whitney Museum, New York", "A simplified nude figure in an interior assembled from photographs, patterns, and flat color — American consumerism as erotic landscape.", "Wesselmann's Great American Nudes combine the traditional reclining nude with the American consumer environment in an audacious conflation.", "male", "American"),
    ("Claes Oldenburg: Floor Cake", "Claes Oldenburg", 1962, "Synthetic polymer paint on canvas filled with foam rubber and cardboard", "Pop Art / Swedish-American", ["soft sculpture","food","pop art","oversized","floor piece"], ["giant cake","soft","food","floor sculpture","domestic"], ["cream","pastel colors","soft form"], "Museum of Modern Art, MoMA", "A giant slice of cake made of canvas and foam rubber lies on the floor.", "Oldenburg's soft sculptures transform hard objects into soft ones and ordinary objects into monuments. Floor Cake was the first.", "male", "Swedish-American"),

    # ── MINIMALISM EXPANDED ───────────────────────────────────────────────
    ("Robert Morris: Untitled (L-Beams)", "Robert Morris", 1965, "Painted plywood (later fiberglass)", "Minimalism / American", ["minimal","geometric","L-shape","three positions","space"], ["L-shaped beams","three orientations","space","perception"], ["grey painted surface","simple form"], "Solomon R. Guggenheim Museum, New York", "Three identical L-shaped plywood beams in three different orientations — one upright, one lying flat, one balanced on two ends.", "Morris demonstrated that the same form looks completely different depending on its orientation. Fundamental to understanding how context changes perception.", "male", "American"),
    ("Carl Andre: Lever", "Carl Andre", 1966, "137 firebricks in a row", "Minimalism / American", ["minimal","floor","linear","bricks","horizontal"], ["single row of bricks","floor","horizontal","industrial","simple"], ["red-brown brick","floor"], "National Gallery of Canada, Ottawa", "137 firebricks laid end-to-end in a single horizontal row on the floor — 'sculpture as place', not as form.", "Andre extended from stacks to rows. He said: 'I am concerned with the properties of the material, not the properties of me.' Sculpture as pure place.", "male", "American"),
    ("Sol LeWitt: Wall Drawing #46", "Sol LeWitt", 1970, "Pencil on wall", "Conceptual / Minimalism", ["conceptual","wall drawing","instructions","systematic","geometric"], ["diagonal lines","wall","pencil","instructions","systematic"], ["pencil grey","white wall"], "Various institutions", "All combinations of two lines crossing at right angles drawn in pencil directly on a white wall according to written instructions.", "LeWitt separated concept from execution — the instructions ARE the artwork. Anyone can execute it. This challenges every assumption about artistic authorship.", "male", "American"),
    ("Eva Hesse: Hang Up", "Eva Hesse", 1966, "Acrylic on cloth over wood, steel", "Post-Minimalism / American", ["post-minimal","absurdist","steel loop","fabric","humor"], ["fabric-wrapped frame","long steel loop","empty","absurdist","humorous"], ["grey cloth","steel wire","empty space"], "Art Institute of Chicago", "A large fabric-wrapped rectangular frame with a long steel rod looping out from one corner — functionless, absurd.", "Hesse called it 'the most ridiculous structure I have ever seen'. The comic futility of the looping rod is deliberate. A critique of Minimalism's seriousness.", "female", "American"),
    ("Richard Serra: One Ton Prop (House of Cards)", "Richard Serra", 1969, "Hot rolled lead antimony", "Process Art / Minimalism", ["sculpture","lead","gravity","process","balance"], ["four lead plates","leaning","balanced by gravity","gravity","precarious"], ["dark grey lead"], "Museum of Modern Art, MoMA", "Four massive lead plates leaned against each other, held in place only by gravity — no welds or fasteners.", "Serra began pouring and propping lead as a direct process. The four plates balance in pure tension — removing one plate would collapse the whole.", "male", "American"),
    ("Bruce Nauman: The True Artist Helps the World by Revealing Mystic Truths", "Bruce Nauman", 1967, "Neon tubing", "Conceptual / American", ["neon","text","conceptual","irony","artist statement"], ["neon text","spiral","statement","artist role","irony"], ["warm blue-pink neon","dark gallery"], "Philadelphia Museum of Art", "A neon spiral sign reading 'The True Artist Helps the World by Revealing Mystic Truths' — both sincere and ironic.", "Nauman made this as his first window sign, modeled on a bar neon sign. The statement is simultaneously a genuine credo and a joke about artistic pretension.", "male", "American"),
    ("On Kawara: Today (Dec. 1, 1978)", "On Kawara", 1978, "Liquitex on canvas", "Conceptual / Japanese", ["conceptual","date painting","language","time","austere"], ["date","white text","grey ground","systematic","daily"], ["dark grey ground","white painted date"], "Various collections", "The date 'DEC. 1, 1978' painted in white on a dark grey ground.", "Kawara painted today's date every day he worked — over 2000 paintings since 1966. If he couldn't finish it in one day, he destroyed it.", "male", "Japanese"),

    # ── PROCESS ART & EARTH ART ───────────────────────────────────────────
    ("Andy Goldsworthy: Rowan Leaves and Holes", "Andy Goldsworthy", 1987, "Rowan leaves arranged on stone", "Land Art / British", ["land art","ephemeral","natural materials","circle","site specific"], ["rowan leaves","circle","holes","stone","temporary"], ["red orange leaves","grey stone","natural patterns"], "Documentation photograph", "Rowan leaves arranged in an interlocking pattern around natural holes in a stone, photographed and allowed to disperse.", "Goldsworthy works with natural materials and gravity. His works are inherently temporary; only the photograph survives.", "male", "British"),
    ("Richard Long: A Line Made by Walking", "Richard Long", 1967, "Photograph of grass flattened by walking", "Land Art / British", ["land art","walking","minimal","photograph","body"], ["line in grass","walking","body","documentation","simple"], ["green grass","grey flattened stripe"], "Tate Modern, London", "A photograph of a straight line in long grass made by repeatedly walking back and forth.", "Long's first major land art work — one of the simplest and most radical. The body moving through landscape as the medium of art.", "male", "British"),
    ("Nancy Holt: Sun Tunnels", "Nancy Holt", 1976, "Concrete tunnels in desert", "Land Art / American", ["land art","astronomical","desert","concrete","light"], ["four tunnels","Utah desert","solstice","star holes","light beams"], ["concrete grey","desert gold","light beams"], "Great Basin Desert, Utah (permanent)", "Four large concrete cylinders in the Utah desert aligned to the summer and winter solstice sunrise and sunset, with star-pattern holes.", "Holt created a monument to astronomical time in the American desert. The tunnels frame the landscape and mark the passage of cosmic time.", "female", "American"),

    # ── NEO-GEO & APPROPRIATION ───────────────────────────────────────────
    ("Jeff Koons: Three Ball Total Equilibrium Tank", "Jeff Koons", 1985, "Glass tank, distilled water, sodium chloride, three basketballs", "Neo-Geo / American", ["neo-geo","basketball","equilibrium","tank","conceptual"], ["basketballs","suspended","water tank","equilibrium","science"], ["clear water","orange basketballs","steel tank"], "Private collection", "Three basketballs suspended at exact mid-point in a tank of sodium chloride solution — neither rising nor sinking.", "Koons's most conceptually pure work. The equilibrium is precise — temperature changes can disturb it. About the moment of perfect balance.", "male", "American"),
    ("Sherrie Levine: After Walker Evans", "Sherrie Levine", 1981, "Photograph (rephotography)", "Appropriation Art / American", ["appropriation","rephotography","authorship","original","conceptual"], ["Great Depression farmer wife","rephotography","Walker Evans copy","authorship"], ["black and white photograph"], "Various collections", "Photographs of Dorothea Lange and Walker Evans's Depression-era documentary photographs, re-photographed without alteration.", "Levine's rephotography attack on originality and male artistic authority launched the Pictures Generation. 'Who owns an image?' asked with precise force.", "female", "American"),
    ("Richard Prince: Untitled (Cowboy)", "Richard Prince", 1989, "Chromogenic print (rephotography)", "Appropriation Art / American", ["appropriation","cowboy","marlboro man","american myth","rephotography"], ["Marlboro cowboy","western landscape","rephotographed","american myth"], ["western blue sky","earth tones","rephotography quality"], "Solomon R. Guggenheim Museum, New York", "A Marlboro cigarette advertisement rephotographed and enlarged — the cowboy as pure American myth.", "Prince's Cowboys expose the power of advertising images to create mythology. The work was at the center of copyright law debates for decades.", "male", "American"),

