    # ── ADDITIONAL PERFORMANCE & BODY ART ────────────────────────────────
    ("Marina Abramović: The Artist Is Present", "Marina Abramović", 2010, "Performance", "Performance Art / Serbian", ["performance","durational","silence","presence","MoMA"], ["artist seated","visitors opposite","silence","duration","endurance"], ["gallery white","two chairs","silent presence"], "Museum of Modern Art, MoMA (736 hours over 3 months)", "Abramović sat silently at a table in MoMA's atrium for 736 hours over three months. Visitors sat opposite her one at a time.", "Over 1400 people sat opposite Abramović during the performance; many wept. The longest solo performance by a museum artist. Redefines what art can do.", "female", "Serbian"),
    ("Marina Abramović: Rhythm 0", "Marina Abramović", 1974, "Performance", "Performance Art / Serbian", ["performance","durational","danger","passive body","transgression"], ["passive artist","72 objects","audience action","6 hours","gun"], ["gallery white","table of objects","body"], "Studio Morra, Naples", "Abramović stood passively for 6 hours while the public used 72 objects (including a loaded gun and knife) on her body.", "The most disturbing performance ever staged. The public escalated to violence — cutting her clothes, pressing the gun to her throat. She wept at the end.", "female", "Serbian"),
    ("Chris Burden: Shoot", "Chris Burden", 1971, "Performance (documentation)", "Performance Art / American", ["performance","danger","shooting","self-inflicted","political"], ["artist shot","rifle","arm","documented","risk"], ["video documentation black white"], "F Space, Santa Ana, California", "Burden had a friend shoot a rifle bullet through his left arm in a gallery.", "The most extreme act of self-inflicted harm in art history. Burden's body-risk performances confronted the Vietnam War's indifference to physical damage.", "male", "American"),
    ("Carolee Schneemann: Meat Joy", "Carolee Schneemann", 1964, "Performance", "Performance Art / American", ["performance","feminist","body","sensory","ritual"], ["raw meat","paint","performers","celebration","body"], ["flesh colors","red raw meat","performance documentation"], "Judson Memorial Church, New York", "Performers writhed together in raw fish, chickens, sausages, and wet paint in an ecstatic body-celebration performance.", "Schneemann's celebration of the body, sexuality, and sensory joy was deliberately opposite to Minimalism's cool rationality. The defining feminist performance work.", "female", "American"),
    ("Vito Acconci: Following Piece", "Vito Acconci", 1969, "Performance (documentation)", "Conceptual Art / American", ["performance","following","urban","surveillance","documentation"], ["following strangers","New York streets","documentation","surveillance"], ["photographic documentation","urban grey"], "Various collections", "For 23 days Acconci followed random strangers through New York City until they entered a private space.", "A precursor of surveillance art. Following makes the artist invisible as author while making the stranger the involuntary subject.", "male", "American"),

